<?php
declare(strict_types=1);
require_once __DIR__.'/../_core/bootstrap.php';require_once __DIR__.'/../_core/CommerceOrders.php';
header('Cache-Control: no-store');header('X-Robots-Tag: noindex, nofollow');header('X-Frame-Options: SAMEORIGIN');
$id=(int)($_GET['id']??0);if(empty($_SESSION['customer_id'])){header('Location: /account/?next='.rawurlencode('/account/order.php?id='.$id));exit;}
$commerce=new \BYPCMS\Core\CommerceOrders($db,$config,BYPCMS_ROOT);
try{$order=$commerce->view($id,(int)$_SESSION['customer_id']);}catch(Throwable $e){http_response_code(404);exit('Заказ не найден. Вернитесь в /account/.');}
$_SESSION['customer_csrf']??=bin2hex(random_bytes(32));$csrf=$_SESSION['customer_csrf'];$user=$auth->user();$available=$commerce->available(!empty($config['app']['debug'])||($user['role']??'')==='owner');
$e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');
?><!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Заказ №<?= $id ?> — BYPCMS</title><link rel="stylesheet" href="/account/account.css"></head><body><main><header><a href="/">BYPCMS</a><a href="/account/">Мои заказы</a><a href="/contacts/">Контакты и реквизиты</a></header><h1>Заказ №<?= $id ?></h1><section><h2><?= $e(ucfirst($order['edition'])) ?> · <?= $e($order['domain']) ?></h2><p><?= $order['license_term']==='annual'?'Лицензия на год':'Пожизненная лицензия' ?></p><ul><?php foreach($order['items']['items']as $item):?><li><?= $e($item['name']) ?> · <?= $e(number_format($item['minor']/100,2,',',' ')) ?> ₽</li><?php endforeach ?></ul><p><strong><?= $order['kind']==='inquiry'?'Лицензионная часть:':'Итого:' ?> <?= $e(number_format($order['amount_minor']/100,2,',',' ')) ?> ₽</strong></p><?php if($order['kind']==='inquiry'):?><p class="notice">Заявка сохранена. Услуги и их окончательную стоимость нужно согласовать с владельцем; онлайн-оплата этого заказа не предлагается.</p><?php endif ?><p id="test" class="notice" hidden>Тестовый платёж: реального списания не было. Выдаётся тестовая лицензия.</p><dl><dt>Оплата</dt><dd id="payment"></dd><dt>Выдача</dt><dd id="fulfillment"></dd><dt>Уведомление</dt><dd id="mail"></dd></dl><p id="detail"></p><p id="error" class="error" role="alert" hidden></p><p id="notice" class="notice" role="status"></p><div class="buttons"><button id="pay" hidden>Перейти к оплате в ЮKassa</button><button id="check">Проверить статус</button><a id="purchase" class="button" hidden>Открыть покупку и скачать CMS</a></div><p><a href="/account/?next=<?= rawurlencode('/account/order.php?id='.$id) ?>">Войти заново</a> · <a href="/order/">Создать другой заказ</a></p><small>Возврат с платёжной страницы не подтверждает оплату. Статус проверяется сервером через ЮKassa. Ошибка письма не отменяет оплаченную покупку.</small></section></main><script>
let order=<?= json_encode($order,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_UNESCAPED_UNICODE) ?>,csrf=<?= json_encode($csrf) ?>,available=<?= $available?'true':'false' ?>,busy=false,polls=0;
const pay=document.querySelector('#pay'),check=document.querySelector('#check'),error=document.querySelector('#error'),notice=document.querySelector('#notice'),purchase=document.querySelector('#purchase');
const paymentLabels={pending:'Ожидает подтверждения',paid:'Оплата подтверждена',canceled:'Платёж отменён'},fulfillmentLabels={pending:'Готовится после оплаты',ready:'Готово',failed:'Оплата сохранена; выдачу нужно повторить',not_needed:'Заявка на согласование'},mailLabels={pending:'В очереди',retry:'Ожидает повторной отправки',accepted:'Принято SMTP-сервером',failed:'Ошибка отправки; владелец уведомлён',uncertain:'Статус доставки уточняется',sending:'Отправляется'};
function render(){document.querySelector('#payment').textContent=order.kind==='inquiry'?'Оплата по согласованию':paymentLabels[order.payment_state]||order.payment_state;document.querySelector('#fulfillment').textContent=fulfillmentLabels[order.fulfillment_state]||order.fulfillment_state;const mail=order.notifications.at(-1);document.querySelector('#mail').textContent=mail?mailLabels[mail.state]||mail.state:'Уведомлений пока нет';document.querySelector('#test').hidden=order.mode!=='test';document.querySelector('#detail').textContent=order.renewed_until?'Продлено до '+order.renewed_until:order.fulfillment_error||order.attempt?.last_error||'';pay.hidden=order.kind==='inquiry'||order.payment_state==='paid'||!available;pay.disabled=busy;check.disabled=busy;check.hidden=order.kind==='inquiry'||!order.attempt;purchase.hidden=!order.purchase_url;if(order.purchase_url)purchase.href=order.purchase_url;if(!available&&order.kind!=='inquiry'&&order.payment_state!=='paid')notice.textContent='Онлайн-оплата временно недоступна. Заказ сохранён в кабинете.';else notice.textContent=busy?'Проверяем состояние заказа…':'';}
async function action(name){if(busy)return;busy=true;error.hidden=true;render();try{const response=await fetch('/commerce/index.php?action='+name,{method:'POST',credentials:'same-origin',cache:'no-store',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify({id:order.id}),signal:AbortSignal.timeout(45000)});const result=await response.json();if(!response.ok){if(result.details?.code==='csrf_expired'){const fresh=await fetch('/commerce/index.php?action=bootstrap',{credentials:'same-origin',cache:'no-store'});const data=await fresh.json();if(fresh.ok)csrf=data.csrf;}throw new Error(result.error||'Сервер не подтвердил действие');}order=result.order;if(typeof result.payments_available==='boolean')available=result.payments_available;if(name==='pay'&&order.attempt?.confirmation_url&&order.payment_state!=='paid')location.assign(order.attempt.confirmation_url);}catch(e){error.textContent=(e.message||'Не удалось связаться с сервером')+'. Заказ не удалён; повторите проверку статуса.';error.hidden=false;}finally{busy=false;render();}}
pay.onclick=()=>action('pay');check.onclick=()=>action('sync');render();if(order.attempt&&!(order.payment_state==='paid'&&order.fulfillment_state==='ready'))void action('sync');
const timer=setInterval(()=>{if(++polls>12||order.payment_state==='canceled'||(order.payment_state==='paid'&&order.fulfillment_state==='ready')){clearInterval(timer);return;}if(order.attempt)void action('sync');},5000);
</script></body></html>
